import java.util.*;

record Result(String name, int score) { }

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), pass = sc.nextInt();
        List<Result> xs = new ArrayList<>();
        for (int i = 0; i < n; i++) xs.add(new Result(sc.next(), sc.nextInt()));
        List<Result> out = xs.stream().filter(r -> r.score() >= pass).sorted(Comparator.comparingInt(Result::score).reversed().thenComparing(Result::name)).toList();
        if (out.isEmpty()) System.out.println("none");
        else out.forEach(r -> System.out.println(r.name() + ":" + r.score()));
    }
}
